entries[280719] = { ["name"] = "Geheimtechnik", ["text"] = "30 Energie / 1 zu 5 Combopunkte Nahkampfreichweite\nSofort 1 min Abklingzeit\nFinishing-Move, der Schattenklone von Euch erschafft. Ihr und Eure Schattenklone führen jeweils einen Angriff aus, der alle Gegner in der Nähe Eures Primärziels durchbohrt und diesem körperlichen Schaden sowie anderen Zielen verringerten Schaden zufügt.\n1 Punkt: insgesamt [(19% der Angriffskraft) * 3] Schaden\n2 Punkte: insgesamt [(19% der Angriffskraft) * 2 * 3] Schaden\n3 Punkte: insgesamt [(19% der Angriffskraft) * 3 * 3] Schaden\n4 Punkte: insgesamt [(19% der Angriffskraft) * 4 * 3] Schaden\n5 Punkte: insgesamt [(19% der Angriffskraft) * 5 * 3] Schaden\n[ 6 Punkte: insgesamt [(19% der Angriffskraft) * 6 * 3] Schaden] [ 7 Punkte: insgesamt [(19% der Angriffskraft) * 7 * 3] Schaden]\nVerringert die Abklingzeit für jeden verbrauchten Combopunkt um 1 Sek." }
entries[280720] = { ["name"] = "Geheimtechnik", ["text"] = "Unbegrenzte Reichweite\nSofort\nFinishing-Move, der Schattenklone von Euch erschafft. Ihr und Eure Schattenklone führen jeweils einen Angriff aus, der alle Gegner in der Nähe Eures Primärziels durchbohrt und diesem körperlichen Schaden sowie anderen Zielen verringerten Schaden zufügt.\n1 Punkt: insgesamt [(19% der Angriffskraft) * 3] Schaden\n2 Punkte: insgesamt [(19% der Angriffskraft) * 2 * 3] Schaden\n3 Punkte: insgesamt [(19% der Angriffskraft) * 3 * 3] Schaden\n4 Punkte: insgesamt [(19% der Angriffskraft) * 4 * 3] Schaden\n5 Punkte: insgesamt [(19% der Angriffskraft) * 5 * 3] Schaden\n[ 6 Punkte: insgesamt [(19% der Angriffskraft) * 6 * 3] Schaden] [ 7 Punkte: insgesamt [(19% der Angriffskraft) * 7 * 3] Schaden]\nVerringert die Abklingzeit für jeden verbrauchten Combopunkt um 1 Sek." }
entries[280721] = { ["name"] = "Plötzlicher Tod", ["text"] = "Ca. 1.7 Procs pro Minute\nEure Angriffe haben eine Chance, die Abklingzeit von Hinrichten' abzuschließen und die Fähigkeit gegen jedes Ziel einsetzbar zu machen, unabhängig von seiner Gesundheit.\n(3s Abklingzeit)" }
