entries[280729] = { ["name"] = "Rasende Teufelskralle", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare rasende Teufelskralle oder gibt sie wieder frei.\n\"Die Legion experimentierte mit dem Verderben vieler verschiedener Wildtiere, wie etwa dieser Spezies von Feuervögeln aus einer Lavawelt.\"\nErfolg:\nEs sind Herdentiere\nKategorie:\nReittiere" }
entries[280730] = { ["name"] = "Reinherzrenner", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Reinherzrenner oder gibt ihn wieder frei.\n\"Die Existenz dieser Renner ist zwar seit Langem bekannt, doch sie freunden sich nur mit denjenigen an, die sich außerordentlich um ihre Freundschaft bemüht haben.\"\nErfolg:\n100 ehrfürchtige Fraktionen\nKategorie:\nRuf" }
