entries[280744] = { ["name"] = "Dämonisches Trampeln", ["text"] = "Sofort 45 sek. Abklingzeit\nDurch den Einsatz von 'Dämonisches Trampeln' erhöht Ihr 5 Sek. lang Eure Bewegungsgeschwindigkeit um 200%, schlagt alle Gegner auf Eurem Weg nieder und fügt ihnen (10.7% der Angriffskraft) körperlichen Schaden zu.\n\nWährend 'Dämonisches Trampeln' aktiv ist, könnt Ihr zwar nicht verlangsamt werden, aber auch keine Zauber wirken oder normale Angriffe ausführen." }
